import json
import unittest
from pathlib import Path

from cycling_devtools.connectivity.qr import encode, render

# Generated by qrcodegen 1.8.0 (Nayuki) in a throwaway environment, not a project dependency.
FIXTURES = json.loads((Path(__file__).parent / 'fixtures/qr_matrices.json').read_text())['cases']


class QrTest(unittest.TestCase):
    def test_matrices_match_the_reference_encoder(self):
        for case in FIXTURES:
            with self.subTest(text=case['text'][:20], version=case['version']):
                expected = [[module == '1' for module in row] for row in case['rows']]
                self.assertEqual(encode(case['text'], mask=case['mask']), expected)

    def test_the_pairing_url_fits_version_5(self):
        url = FIXTURES[0]['text']
        self.assertEqual(len(encode(url)), 5 * 4 + 17)

    def test_texts_beyond_version_10_are_refused(self):
        with self.assertRaises(ValueError):
            encode('x' * 214)

    def test_render_fills_light_modules_unless_inverted(self):
        dark = [[True]]
        self.assertEqual(render(dark, quiet=1).splitlines(), ['█▀█', '███'])
        self.assertEqual(render(dark, invert=True, quiet=1).splitlines(), [' ▄ ', '   '])


if __name__ == '__main__':
    unittest.main()
